    return json.dumps(obj, sort_keys=True, separators=(',', ':'), allow_nan=False)


def run(req):
    data = json.dumps(req, separators=(',', ':')).encode()
    try:
        got = pipeline.execute(formats.read_request(io.BytesIO(data)))
    except (ValueError, UnicodeError, RecursionError):
        got = {'error': 'invalid_request'}
    try:
        want = ref.solve(json.loads(data.decode()))
    except ref.Invalid:
        want = {'error': 'invalid_request'}
    except Exception as exc:
        want = 'REF-CRASH %r' % (exc,)
    if canon(got) != canon(want):
        FAILS.append('reference disagreement')
        print('REF DIFF', json.dumps(req)[:300])
        print('  got ', canon(got)[:600])
        print('  want', canon(want)[:600])
    return got""")
